import{z as A,x as l,o as t,c as p,q as i,j as r,D as e,d as n,s,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"匹配与倾向得分","description":"","frontmatter":{"title":"匹配与倾向得分","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/matching-propensity.md","filePath":"econ/matching-propensity.md","lastUpdated":1791063341000}'),d={name:"econ/matching-propensity.md"};function m(h,a,c,D,u,T){const o=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="匹配与倾向得分" tabindex="-1">匹配与倾向得分 <a class="header-anchor" href="#匹配与倾向得分" aria-label="Permalink to &quot;匹配与倾向得分&quot;">​</a></h1><div class="epigraph"><p>若赋值只通过可观测 $X$ 选择，则在 $X$ 的细胞里比较处理与对照就回到随机化；倾向得分把细胞从高维 $X$ 压成一维概率。</p><footer>—— Rosenbaum and Rubin, The Central Role of the Propensity Score, Biometrika 1983；Heckman, Ichimura and Todd, Matching as an Econometric Evaluation Estimator, RES 1998</footer></div><p><a href="/econ/synthetic-control">上一课</a>用凸权构造<strong>一个</strong>处理单位的反事实路径。本课缺口是许多单位、处理在截面上选择：匹配与倾向得分。<a href="/econ/event-study-econ">事件研究</a>下一课把公告窗口写成设计；固定效应更后才把选择收到时不变未观测。本课先假设选择可观测（CIA）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>条件独立：\\(Y(1),Y(0)\\perp D\\mid X\\)，再加重叠 \\(0\\lt P(D=1\\mid X)\\lt 1\\)。则在 \\(X=x\\) 的细胞里，处理对照均值差识别 \\(\\mathbb{E}[\\tau\\mid X=x]\\)，再对处理组分布积分得 ATT。缺口是维数：\\(X\\) 一多，细胞空。Rosenbaum–Rubin：倾向得分 \\(e(X)=P(D=1\\mid X)\\) 是平衡得分，条件于 \\(e(X)\\) 同样有 CIA。于是匹配、分层、加权（IPW）都在 \\(e(X)\\) 上操作。</p><p><span class="marginnote">术语翻译：倾向得分就是「可观测特征相同的人里，接受处理的比例」。例如 40 岁、十年工龄的申请者有 30% 参加了培训，这 30% 就是他们的倾向得分。按它分组后，组内参加与否就近似抛硬币——这正是 Rosenbaum–Rubin 把高维 \\(X\\) 压成一维的把戏。</span></p><p>Heckman–Ichimura–Todd 把匹配写成核：用对照的核加权平均当 \\(\\hat Y_i(0)\\)。重叠失败时（处理组跑到 \\(e\\) 的尾部无人对照）不要外推——与合成控制的凸包禁令同族。</p><p><span class="marginnote">CIA 不可检验。平衡检验只说明给定 \\(X\\)（或 \\(\\hat e\\)）后，<strong>可观测</strong>的均值接近；未观测选择仍在，那是 OVB，不是匹配能洗掉的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计 \\(e(X)\\)：logit / probit，或后课机器学习。然后：最近邻匹配、核匹配、分层、IPW（Horvitz–Thompson）。Doubly robust：结果回归与倾向加权一个对就一致。报告重叠图、平衡表、共同支撑上的 ATT。不要用处理后再测的 \\(X\\)（坏控制）。</p>',10)),(t(),r(B,null,{default:e(()=>[s(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CIA%5B%22CIA%3A%20%E9%80%89%E6%8B%A9%E5%8F%AA%E7%BB%8F%20X%22%5D%20--%3E%20CELL%5B%22%E7%BB%86%E8%83%9E%E5%86%85%E5%AF%B9%E7%85%A7%22%5D%0A%20%20PS%5B%22%E5%80%BE%E5%90%91%E5%BE%97%E5%88%86%20e(X)%22%5D%20--%3E%20DIM%5B%22%E9%99%8D%E7%BB%B4%E4%BB%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20CELL%20--%3E%20ATT%5B%22%E5%AF%B9%E5%A4%84%E7%90%86%E5%88%86%E5%B8%83%E7%A7%AF%E5%88%86%20ATT%22%5D%0A%20%20PS%20--%3E%20ATT%0A%20%20OV%5B%22%E9%87%8D%E5%8F%A0%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20STOP%5B%22%E4%B8%8D%E5%A4%96%E6%8E%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"标准误要计入 \\(\\hat e\\) 的第一步；Abadie–Imbens 对最近邻匹配给出渐近修正。朴素 bootstrap 对离散匹配可能失效。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是在可观测上重建随机化。倾向得分是降维装置，不是新的识别。识别仍是 CIA + 重叠。IPW 把「对照里稀有的 \\(X\\)」放大，方差在尾部爆炸——这是重叠的价格。匹配丢弃无法配对的单位，换外部有效为内部有效。",-1)),(t(),r(B,null,{default:e(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%AB%98%E7%BB%B4%E5%8D%8F%E5%8F%98%E9%87%8F%20X%22%5D%20--%3E%20E%5B%22%E5%8E%8B%E7%BC%A9%E6%88%90%E4%B8%80%E7%BB%B4%20e(X)%20%3D%20P(D%3D1%7CX)%22%5D%0A%20%20E%20--%3E%20BAL%5B%22%E7%BB%99%E5%AE%9A%20e%EF%BC%9A%E4%B8%A4%E7%BB%84%E7%9A%84%20X%20%E5%88%86%E5%B8%83%E7%9B%B8%E5%90%8C%22%5D%0A%20%20BAL%20--%3E%20RAND%5B%22%E7%9B%B8%E5%BD%93%E4%BA%8E%E5%9C%A8%20e%20%E7%9A%84%E5%88%86%E5%B1%82%E5%86%85%E5%81%9A%E4%BA%86%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%0A%20%20RAND%20--%3E%20CMP%5B%22%E7%BB%84%E5%86%85%E5%9D%87%E5%80%BC%E5%B7%AE%20%3D%20%E5%9B%A0%E6%9E%9C%E6%95%88%E5%BA%94%22%5D%0A%20%20TAIL%5B%22e%20%E9%80%BC%E8%BF%91%200%20%E6%88%96%201%20%E7%9A%84%E5%B0%BE%E9%83%A8%22%5D%20--%3E%20W%5B%22IPW%20%E6%9D%83%E9%87%8D%E7%88%86%E7%82%B8%EF%BC%8C%E6%96%B9%E5%B7%AE%E5%A4%B1%E6%8E%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>与 RDD：RDD 只在门槛局部不需要 CIA 对全局 \\(X\\)。匹配声称全局（在支撑上）CIA，更强。与 IV：IV 允许未观测选择，换排除约束。三套设计不要混成「我控制了很多所以因果」。</p><p><span class="marginnote">数字实例：某对照单位的 \\(\\hat e=0.9\\)（像处理组的人），IPW 要给它 \\(1/(1-0.9)=10\\) 倍权重；若 \\(\\hat e=0.99\\)，权重就是 100 倍。少数尾部单位主导整个估计量，一个异常值就能掀翻标准误——这就是「IPW 尾部方差大」的数字版。</span></p><p><span class="marginnote">Dehejia–Wahba 用 Lalonde 实验基准演示：实验 ATE 当真理，观测匹配能贴近——前提是 \\(X\\) 足够。换一套 \\(X\\)，贴近可以消失。这是敏感性，不是一次胜利。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把倾向得分写成机器学习竞赛。不估计未观测选择的 Heckman 两步全文——那是选择模型，识别靠排除，与 CIA 是两条路。下一课事件研究：把公告日附近的累积异常写成设计，仍在可观测选择这一侧。量化栏的配对交易不是本课匹配。</p><p><span class="marginnote">常见误区：初学者容易把「平衡表通过」当成识别成立。平衡检验只核对可观测的 \\(X\\) 在两组间对齐；若有「动机决定参训」这类未观测变量在背后，匹配无能为力——CIA 是假设，不是检验能给出的结论。把「通过平衡」写成「已证明因果」，是把检查表误当成了证明。</span></p><p>后课默认：匹配 / IPW 的参数是 CIA 支撑上的 ATT 或 ATE；平衡不是识别证明。公告窗的事件研究下一课；未观测时不变异质更后交给 FE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIA + 重叠 ⇒ 细胞比较识别条件效应。</li><li>倾向得分是平衡得分，用来降维，不削弱假设。</li><li>重叠差则停止外推；IPW 尾部方差大。</li><li>平衡检验只管可观测。</li><li>出处：Rosenbaum and Rubin, <em>Biometrika</em> 1983；Heckman, Ichimura and Todd, <em>RES</em> 1998。</li></ul>',9))])}const I=A(d,[["render",m]]);export{b as __pageData,I as default};
